import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.shared.aashell.genericaashell import GenericAashell


class Rad(GenericAashell):
    """Rad command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Rad command.

        :param connection: moler connection to device, terminal when command is executed
        :param options: parameter with which the command will be executed
        :param prompt: Prompt of the starting shell
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Rad, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self.current_ret["RESULT"] = {}

    def build_command_string(self):
        """
        Build command string.

        :return: String representation of command to send over connection to device.
        """
        cmd = "rad"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Execute all parsing methods.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_not_registered_error(line)
                self._parse_no_parameter_error(line)
                self._parse_unknown_option_error(line)
                self._parse_change_parameters(line)
                self._parse_print_parameters(line)
                self._parse_registered_domains(line)
                self._parse_non_default_rnd_parameters(line)
                self._parse_restore_factory_defaults(line)
            except ParsingDone:
                pass
        return super(Rad, self).on_new_line(line, is_full_line)

    # domain not registered
    _re_not_registered = re.compile(r"(?P<NOT_REGISTERED>not\sregistered)", re.I)

    def _parse_not_registered_error(self, line):
        if self._regex_helper.search_compiled(Rad._re_not_registered, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("NOT_REGISTERED")))
            raise ParsingDone

    #  no parameter found
    _re_no_parameter = re.compile(r"(?P<NO_PARAMETER>No\sparameter)")

    def _parse_no_parameter_error(self, line):
        if self._regex_helper.search_compiled(Rad._re_no_parameter, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("NO_PARAMETER")))
            raise ParsingDone

    # Unknown option
    _re_unknown_option = re.compile(r"(?P<UNKNOWN_OPTION>Unknown\soption)", re.I)

    def _parse_unknown_option_error(self, line):
        if self._regex_helper.search_compiled(Rad._re_unknown_option, line):
            self.set_exception(CommandFailure(self, self._regex_helper.group("UNKNOWN_OPTION")))
            raise ParsingDone

    # [0xF0020] 'Unknown' = 0x2 (2) written succesfully for domain 15
    _re_change_parameters = re.compile(r"(?P<CHANGE_PARAMETERS>^\[(?P<PARAM>.+)\]\s+'(?P<NAME>.+)'\s*=\s*(?P<VALUE>.+)\s+\(\d+\)\D+(?P<DOMAIN>\d+))")

    def _parse_change_parameters(self, line):
        if self._regex_helper.search_compiled(Rad._re_change_parameters, line):
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["name"] = self._regex_helper.group("NAME")
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["value"] = self._regex_helper.group("VALUE")
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["domain"] = self._regex_helper.group("DOMAIN")
            raise ParsingDone

    # [0x10042] 'AaSysLogUdpAddress' = 0xC0A8FF7E
    _re_print_parameters = re.compile(r"(?P<PRINT_PARAMETERS>^\[(?P<PARAM>.+)\]\s+'(?P<NAME>.+)'\s*=\s*(?P<VALUE>.+))", re.MULTILINE)

    def _parse_print_parameters(self, line):
        if self._regex_helper.search_compiled(Rad._re_print_parameters, line):
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["name"] = self._regex_helper.group("NAME")
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["value"] = self._regex_helper.group("VALUE")
            raise ParsingDone

    # [35] 'EXTLOG'
    _re_registered_domains = re.compile(r"(?P<REGISTERED_DOMAINS>^\[(?P<ID>\d+)\]\s*'(?P<NAME>.+)'$)")

    def _parse_registered_domains(self, line):
        if self._regex_helper.search_compiled(Rad._re_registered_domains, line):
            self.current_ret["RESULT"][self._regex_helper.group("ID")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("ID")]["name"] = self._regex_helper.group("NAME")
            raise ParsingDone

    # [0x100B7] Default val = 0x0; Current val = 0x1
    _re_non_default_rnd_parameters = re.compile(
        r"(?P<NON_DEFAULT_PARAMETERS>^\[(?P<PARAM>.+)\]\s+(\w+\s+\w+)\s+=\s+(?P<DEFAULT_VAL>.+);\s+(\w+\s+\w+)\s+=\s+(?P<CURRENT_VAL>.+))"
    )

    def _parse_non_default_rnd_parameters(self, line):
        if self._regex_helper.search_compiled(Rad._re_non_default_rnd_parameters, line):
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")] = {}
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["default_val"] = self._regex_helper.group("CURRENT_VAL")
            self.current_ret["RESULT"][self._regex_helper.group("PARAM")]["current_val"] = self._regex_helper.group("DEFAULT_VAL")
            raise ParsingDone

    # Successfully restored factory defaults
    _re_restore_factory_defaults = re.compile(r"(?P<RESTORE_FACTORY_DEFAULTS>Successfully\srestored)")

    def _parse_restore_factory_defaults(self, line):
        if self._regex_helper.search_compiled(Rad._re_restore_factory_defaults, line):
            raise ParsingDone


